using System.Net.Mail;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using MadaAcademy.Api.Modules.Operations;
using MadaAcademy.Api.Persistence;
using MadaAcademy.Api.Persistence.Entities;
using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;

namespace MadaAcademy.Api.Modules.Identity;

public static class StaffGuardianBulkImportEndpoints
{
    private const long MaxBytes = 5 * 1024 * 1024;
    private static readonly TimeSpan PreviewLifetime = TimeSpan.FromHours(24);
    private const string SP = "BULK_IMPORT_STAFF_PREVIEW_CREATED", SC = "BULK_IMPORT_STAFF_COMMITTED", GP = "BULK_IMPORT_GUARDIAN_PREVIEW_CREATED", GC = "BULK_IMPORT_GUARDIAN_COMMITTED";

    public static IEndpointRouteBuilder MapMadaStaffGuardianBulkImportEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var staff = endpoints.MapGroup("/api/v1/imports/staff").RequireAuthorization("academy-owner");
        staff.MapPost("/csv/preview", PreviewStaffAsync); staff.MapPost("/commit", CommitStaffAsync);
        var guardians = endpoints.MapGroup("/api/v1/imports/guardians").RequireAuthorization("staff");
        guardians.MapPost("/csv/preview", PreviewGuardiansAsync); guardians.MapPost("/commit", CommitGuardiansAsync);
        return endpoints;
    }

    private static async Task<IResult> PreviewStaffAsync(HttpRequest request, ClaimsPrincipal user, MadaDbContext db, CancellationToken ct)
    {
        if (!Tenant(user, out var tenantId)) return Error(403, "MISSING_ACADEMY_SCOPE", "Missing academy scope.");
        var upload = await Upload(request, ct); if (upload.Error is not null) return upload.Error;
        var rows = ParseStaff(upload.Bytes!, out var parseErrors); if (parseErrors.Count > 0) return Validation(parseErrors); if (rows.Count is 0 or > 1000) return Error(400, "ROW_LIMIT", "CSV must contain 1 to 1000 rows.");
        var roles = RoleCatalog.All.Where(x => x.AssignableByAcademyOwner).Select(x => x.Code).ToHashSet(); var branches = await db.Branches.AsNoTracking().Where(x => x.TenantId == tenantId && x.Status == "ACTIVE").Select(x => x.Id).ToHashSetAsync(ct); var emails = (await db.UserAccounts.AsNoTracking().Where(x => x.Email != null).Select(x => x.Email!).ToListAsync(ct)).Select(x => x.ToUpperInvariant()).ToHashSet(); var phones = (await db.UserAccounts.AsNoTracking().Where(x => x.AccountType == "staff").Select(x => x.Phone).ToListAsync(ct)).ToHashSet(); var seen = new HashSet<string>();
        var preview = rows.Select((row, i) => { var errors = new List<string>(); var email = row.Email.Trim().ToLowerInvariant(); var phone = Normalize(row.Phone); var role = row.RoleCode.Trim().ToUpperInvariant(); try { _ = new MailAddress(email); } catch { errors.Add("email is invalid."); } if (row.Name.Trim().Length is < 2 or > 160) errors.Add("fullName must be between 2 and 160 characters."); if (!roles.Contains(role)) errors.Add("roleCode is not assignable by the academy owner."); if (row.BranchId is not null && !branches.Contains(row.BranchId.Value)) errors.Add("branchId is not an active branch in this academy."); if (!seen.Add(email) || !seen.Add(phone) || emails.Contains(email.ToUpperInvariant()) || phones.Contains(phone)) errors.Add("email or phone already exists or appears more than once."); return new StaffPreviewRow(i + 1, row.Name.Trim(), email, phone, role, row.BranchId, errors.Count == 0 ? "CREATE" : "REVIEW", errors); }).ToArray();
        return await Save(db, user, tenantId, SP, "BULK_IMPORT_STAFF_PREVIEW", preview, upload.Bytes!, upload.Name!, ct);
    }

    private static async Task<IResult> CommitStaffAsync(StaffCommitRequest request, ClaimsPrincipal user, MadaDbContext db, CancellationToken ct)
    {
        if (!Tenant(user, out var tenantId)) return Error(403, "MISSING_ACADEMY_SCOPE", "Missing academy scope."); var stored = await Load<StoredStaff>(db, tenantId, SP, request.PreviewId, ct); if (stored is null) return Error(404, "PREVIEW_NOT_FOUND", "Staff preview was not found."); var invalid = ValidateCommit(stored.Hash, stored.Source, request.PreviewHash, request.SourceFile); if (invalid is not null) return invalid; if (stored.Rows.Any(x => x.Action != "CREATE")) return Error(409, "PREVIEW_REQUIRES_REVIEW", "Resolve every REVIEW row before committing."); if (await ExistsCommit(db, tenantId, SC, request.PreviewId, ct)) return Error(409, "PREVIEW_ALREADY_COMMITTED", "This preview has already been committed.");
        var existingPhones = (await db.UserAccounts.Where(x => x.AccountType == "staff").Select(x => x.Phone).ToListAsync(ct)).ToHashSet(); if (stored.Rows.Any(x => existingPhones.Contains(x.Phone))) return Error(409, "PREVIEW_STALE", "A staff phone changed after preview."); var accounts = stored.Rows.Select(x => new UserAccount { Email = x.Email, Phone = x.Phone, DisplayName = x.Name, AccountType = "staff", Status = "INVITED" }).ToArray(); db.UserAccounts.AddRange(accounts); var memberships = accounts.Zip(stored.Rows, (account, row) => new Membership { UserAccountId = account.Id, TenantId = tenantId, BranchId = row.BranchId, RoleCode = row.RoleCode, ScopeLevel = row.BranchId.HasValue ? "BRANCH" : "TENANT", Status = "ACTIVE" }).ToArray(); db.Memberships.AddRange(memberships); foreach (var pair in accounts.Zip(stored.Rows)) db.Invitations.Add(new Invitation { Email = pair.Second.Email, TenantId = tenantId, BranchId = pair.Second.BranchId, RoleCode = pair.Second.RoleCode, TokenHash = Hash(RandomNumberGenerator.GetBytes(32)), ExpiresAt = DateTimeOffset.UtcNow.AddDays(7), Status = "PENDING" }); db.AuditEvents.Add(new AuditEvent { ActorUserId = Actor(user), TenantId = tenantId, Action = SC, TargetType = "BULK_IMPORT_STAFF_PREVIEW", TargetId = request.PreviewId.ToString(), Reason = "Invitation-first staff CSV committed; no password was imported or stored.", MetadataJson = JsonSerializer.Serialize(new { previewId = request.PreviewId, createdCount = accounts.Length, state = "COMMITTED" }) }); await db.SaveChangesAsync(ct); return Results.Ok(new { data = new { request.PreviewId, createdCount = accounts.Length, state = "COMMITTED", userIds = accounts.Select(x => x.Id).ToArray() } });
    }

    private static async Task<IResult> PreviewGuardiansAsync(HttpRequest request, ClaimsPrincipal user, MadaDbContext db, CancellationToken ct)
    {
        if (!CanGuardianImport(user) || !Tenant(user, out var tenantId)) return Error(403, "IMPORT_FORBIDDEN", "This role cannot import guardians."); var upload = await Upload(request, ct); if (upload.Error is not null) return upload.Error; var rows = ParseGuardians(upload.Bytes!, out var parseErrors); if (parseErrors.Count > 0) return Validation(parseErrors); if (rows.Count is 0 or > 1000) return Error(400, "ROW_LIMIT", "CSV must contain 1 to 1000 rows."); var branchScope = Guid.TryParse(user.FindFirstValue("branchId"), out var branch) ? branch : (Guid?)null; var studentIds = rows.Select(x => x.StudentId).ToArray(); var allowed = await db.Students.AsNoTracking().Where(x => x.TenantId == tenantId && studentIds.Contains(x.Id) && (!branchScope.HasValue || x.BranchId == branchScope.Value)).Select(x => x.Id).ToHashSetAsync(ct); var phones = (await db.UserAccounts.AsNoTracking().Where(x => x.AccountType == "parent").Select(x => x.Phone).ToListAsync(ct)).ToHashSet(); var seen = new HashSet<string>(); var preview = rows.Select((row, i) => { var errors = new List<string>(); var phone = Normalize(row.Phone); if (!allowed.Contains(row.StudentId)) errors.Add("studentId is outside the current academy/branch scope."); if (phone.Length < 8) errors.Add("phone is invalid."); if (row.Name.Trim().Length is < 2 or > 160) errors.Add("displayName must be between 2 and 160 characters."); if (row.Relationship.Trim().Length is < 1 or > 64) errors.Add("relationship is required and must be at most 64 characters."); if (!seen.Add($"{phone}|{row.StudentId}") || phones.Contains(phone)) errors.Add("guardian phone/link already exists or appears twice."); return new GuardianPreviewRow(i + 1, row.StudentId, phone, row.Name.Trim(), row.Relationship.Trim(), row.Email?.Trim().ToLowerInvariant(), errors.Count == 0 ? "CREATE" : "REVIEW", errors); }).ToArray(); return await Save(db, user, tenantId, GP, "BULK_IMPORT_GUARDIAN_PREVIEW", preview, upload.Bytes!, upload.Name!, ct);
    }

    private static async Task<IResult> CommitGuardiansAsync(GuardianCommitRequest request, ClaimsPrincipal user, MadaDbContext db, CancellationToken ct)
    {
        if (!CanGuardianImport(user) || !Tenant(user, out var tenantId)) return Error(403, "IMPORT_FORBIDDEN", "This role cannot import guardians."); var stored = await Load<StoredGuardian>(db, tenantId, GP, request.PreviewId, ct); if (stored is null) return Error(404, "PREVIEW_NOT_FOUND", "Guardian preview was not found."); var invalid = ValidateCommit(stored.Hash, stored.Source, request.PreviewHash, request.SourceFile); if (invalid is not null) return invalid; if (stored.Rows.Any(x => x.Action != "CREATE")) return Error(409, "PREVIEW_REQUIRES_REVIEW", "Resolve every REVIEW row before committing."); if (await ExistsCommit(db, tenantId, GC, request.PreviewId, ct)) return Error(409, "PREVIEW_ALREADY_COMMITTED", "This preview has already been committed."); var students = await db.Students.AsNoTracking().Where(x => x.TenantId == tenantId).Select(x => x.Id).ToHashSetAsync(ct); if (stored.Rows.Any(x => !students.Contains(x.StudentId))) return Error(409, "PREVIEW_STALE", "A student changed after preview."); var phones = (await db.UserAccounts.Where(x => x.AccountType == "parent").Select(x => x.Phone).ToListAsync(ct)).ToHashSet(); var accounts = new List<UserAccount>(); var links = new List<GuardianStudentLink>(); foreach (var row in stored.Rows) { if (!phones.Add(row.Phone)) return Error(409, "PREVIEW_STALE", "A guardian phone changed after preview."); var account = new UserAccount { Phone = row.Phone, Email = row.Email, DisplayName = row.Name, AccountType = "parent", Status = "ACTIVE" }; accounts.Add(account); db.Memberships.Add(new Membership { UserAccountId = account.Id, TenantId = tenantId, RoleCode = "R08_PARENT", ScopeLevel = "TENANT", Status = "ACTIVE" }); links.Add(new GuardianStudentLink { TenantId = tenantId, StudentId = row.StudentId, UserAccountId = account.Id, CreatedByUserId = Actor(user), Relationship = row.Relationship, Status = "ACTIVE" }); } db.UserAccounts.AddRange(accounts); db.GuardianStudentLinks.AddRange(links); db.AuditEvents.Add(new AuditEvent { ActorUserId = Actor(user), TenantId = tenantId, Action = GC, TargetType = "BULK_IMPORT_GUARDIAN_PREVIEW", TargetId = request.PreviewId.ToString(), Reason = "Guardian CSV and links committed after source identity and stale-data validation.", MetadataJson = JsonSerializer.Serialize(new { previewId = request.PreviewId, createdCount = accounts.Count, linkedCount = links.Count, state = "COMMITTED" }) }); await db.SaveChangesAsync(ct); return Results.Ok(new { data = new { request.PreviewId, createdCount = accounts.Count, linkedCount = links.Count, state = "COMMITTED" } });
    }

    private static async Task<IResult> Save<T>(MadaDbContext db, ClaimsPrincipal user, Guid tenantId, string action, string target, IReadOnlyList<T> rows, byte[] bytes, string name, CancellationToken ct) { var source = MakeSource(bytes, name); var id = Guid.NewGuid(); var hash = Hash(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(rows))); var metadata = action == SP ? JsonSerializer.Serialize(new StoredStaff(id, hash, "PREVIEWED", (IReadOnlyList<StaffPreviewRow>)rows, source)) : JsonSerializer.Serialize(new StoredGuardian(id, hash, "PREVIEWED", (IReadOnlyList<GuardianPreviewRow>)rows, source)); db.AuditEvents.Add(new AuditEvent { ActorUserId = Actor(user), TenantId = tenantId, Action = action, TargetType = target, TargetId = id.ToString(), Reason = "CSV preview created; no records were written.", MetadataJson = metadata }); await db.SaveChangesAsync(ct); return Results.Ok(new { data = new { previewId = id, previewHash = hash, rows, sourceFile = source } }); }
    private static async Task<(byte[]? Bytes, string? Name, IResult? Error)> Upload(HttpRequest request, CancellationToken ct) { var form = await request.ReadFormAsync(ct); var file = form.Files.GetFile("file"); if (file is null || file.Length == 0 || file.Length > MaxBytes || !Path.GetExtension(file.FileName).Equals(".csv", StringComparison.OrdinalIgnoreCase)) return (null, null, Error(400, "FILE_INVALID", "A non-empty CSV file up to 5 MB with .csv extension is required.")); await using var input = file.OpenReadStream(); await using var ms = new MemoryStream(); await input.CopyToAsync(ms, ct); return (ms.ToArray(), Path.GetFileName(file.FileName).Trim(), null); }
    private static async Task<T?> Load<T>(MadaDbContext db, Guid tenant, string action, Guid id, CancellationToken ct) { var item = await db.AuditEvents.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Action == action && x.TargetId == id.ToString(), ct); return item?.MetadataJson is null ? default : JsonSerializer.Deserialize<T>(item.MetadataJson); }
    private static Task<bool> ExistsCommit(MadaDbContext db, Guid tenant, string action, Guid id, CancellationToken ct) => db.AuditEvents.AnyAsync(x => x.TenantId == tenant && x.Action == action && x.TargetId == id.ToString(), ct);
    private static IResult? ValidateCommit(string hash, SourceFileIdentity expected, string suppliedHash, SourceFileIdentity? supplied) => expected.ExpiresAt <= DateTimeOffset.UtcNow ? Error(410, "PREVIEW_EXPIRED", "The CSV preview expired.") : hash != suppliedHash ? Error(409, "PREVIEW_HASH_MISMATCH", "The preview hash does not match.") : supplied is null || expected.Name != supplied.Name || expected.Size != supplied.Size || expected.Hash != supplied.Hash ? Error(409, "SOURCE_FILE_MISMATCH", "The source file identity does not match.") : null;
    private static StaffRow[] ParseStaff(byte[] bytes, out List<string> errors) { errors = []; var lines = Lines(bytes); if (lines.Length < 2 || lines[0].ToLowerInvariant() != "fullname,email,phone,rolecode,branchid") { errors.Add("Header must be fullName,email,phone,roleCode,branchId."); return []; } return lines.Skip(1).Select(x => x.Split(',')).Where(x => x.Length == 5).Select(x => new StaffRow(x[0], x[1], x[2], x[3], Guid.TryParse(x[4], out var id) ? id : null)).ToArray(); }
    private static GuardianRow[] ParseGuardians(byte[] bytes, out List<string> errors) { errors = []; var lines = Lines(bytes); if (lines.Length < 2 || lines[0].ToLowerInvariant() != "studentid,phone,displayname,relationship,email") { errors.Add("Header must be studentId,phone,displayName,relationship,email."); return []; } return lines.Skip(1).Select(x => x.Split(',')).Where(x => x.Length == 5 && Guid.TryParse(x[0], out _)).Select(x => new GuardianRow(Guid.Parse(x[0]), x[1], x[2], x[3], string.IsNullOrWhiteSpace(x[4]) ? null : x[4])).ToArray(); }
    private static string[] Lines(byte[] b) => Encoding.UTF8.GetString(b).TrimStart('\uFEFF').Split('\n').Select(x => x.TrimEnd('\r')).Where(x => !string.IsNullOrWhiteSpace(x)).ToArray(); private static string Normalize(string x) => x.Trim(); private static string Hash(byte[] x) => Convert.ToHexString(SHA256.HashData(x)).ToLowerInvariant(); private static SourceFileIdentity MakeSource(byte[] bytes, string name) { var now = DateTimeOffset.UtcNow; return new SourceFileIdentity(name, bytes.Length, Hash(bytes), now, now.Add(PreviewLifetime)); } private static string Hash(ReadOnlySpan<byte> x) => Convert.ToHexString(SHA256.HashData(x)).ToLowerInvariant(); private static bool Tenant(ClaimsPrincipal p, out Guid id) => Guid.TryParse(p.FindFirstValue("tenantId"), out id); private static Guid? Actor(ClaimsPrincipal p) => Guid.TryParse(p.FindFirstValue("sub"), out var id) ? id : null; private static bool CanGuardianImport(ClaimsPrincipal p) => p.IsInRole("R01_ACADEMY_OWNER") || p.IsInRole("R02_BRANCH_MANAGER") || p.IsInRole("R05_SECRETARY"); private static IResult Validation(List<string> e) => Results.ValidationProblem(new Dictionary<string, string[]> { ["file"] = e.ToArray() }); private static IResult Error(int s, string c, string m) => Results.Json(new { error = new { code = c, message = m } }, statusCode: s);
}
public sealed record StaffRow(string Name, string Email, string Phone, string RoleCode, Guid? BranchId); public sealed record StaffPreviewRow(int RowNumber, string Name, string Email, string Phone, string RoleCode, Guid? BranchId, string Action, IReadOnlyList<string> Errors); public sealed record StoredStaff(Guid PreviewId, string Hash, string State, IReadOnlyList<StaffPreviewRow> Rows, SourceFileIdentity Source); public sealed record StaffCommitRequest(Guid PreviewId, string PreviewHash, SourceFileIdentity? SourceFile); public sealed record GuardianRow(Guid StudentId, string Phone, string Name, string Relationship, string? Email); public sealed record GuardianPreviewRow(int RowNumber, Guid StudentId, string Phone, string Name, string Relationship, string? Email, string Action, IReadOnlyList<string> Errors); public sealed record StoredGuardian(Guid PreviewId, string Hash, string State, IReadOnlyList<GuardianPreviewRow> Rows, SourceFileIdentity Source); public sealed record GuardianCommitRequest(Guid PreviewId, string PreviewHash, SourceFileIdentity? SourceFile);
